/*
Macro that is TRUE if the instantiation request and/or template information
files should be generated.  This is not done when doing preprocessing
only or when the back end is suppressed.  It is also done only for the
primary translation unit.
*/
#define generate_template_files()					\
  (!do_preprocessing_only && !suppress_back_end && is_primary_translation_unit)

/*
Macro that is TRUE if template instantiation flags should be generated.
*/
#define instantiation_flags_needed()					\
  (automatic_instantiation_mode && !suppress_instantiation_flags)

/*
Macro that is TRUE if there are any template instantiations needed for
this compilation.  This is TRUE whether or not the instantiations are
provided by this file.  This is used to determine whether to create a
template information file.
*/
#define any_instantiations_required()					\
  (master_instantiations_list != NULL ||				\
   inline_function_list != NULL ||					\
   inline_variable_list != NULL ||					\
   exported_templates_list != NULL)


