void init_templ_decl_state(a_tmpl_decl_state_ptr tdsp,
                           a_decl_parse_state    *dps)
/*
Initialize a template declaration state block.
*/
{
  tdsp->decl_parse = dps;
  tdsp->sym = NULL;
  dps->function_definition_allowed = TRUE;
  dps->trailing_return_type_allowed = trailing_return_types_enabled;
  tdsp->is_template_friend = FALSE;
  tdsp->is_member_decl = FALSE;
  tdsp->is_specialization = FALSE;
  tdsp->is_partial_specialization = FALSE;
  tdsp->is_full_specialization = FALSE;
  tdsp->defines_something = FALSE;
  tdsp->is_deleted = FALSE;
  tdsp->in_prototype_instantiation = FALSE;
  tdsp->in_generic_definition = FALSE;
  tdsp->decl_scope_err = FALSE;
  tdsp->nesting_depth_err = FALSE;
  tdsp->friend_depth = 0;
  tdsp->export_present = FALSE;
  tdsp->partial_spec_outside_of_class = FALSE;
  tdsp->partial_spec_outside_of_class_template = FALSE;
  tdsp->out_of_class_instantiation = FALSE;
  tdsp->is_template_template_param = FALSE;
  tdsp->is_template_template_param_rescan = FALSE;
  /* Because the __bases and __direct_bases use the variadic mechanism,
     all template declaration contexts must be considered variadic. */
  tdsp->is_variadic = gnu_bases_operators_enabled;
  tdsp->has_variadic_template_params = FALSE;
  tdsp->is_generic = FALSE;
  tdsp->is_delegate = FALSE;
  tdsp->is_lambda = FALSE;
  tdsp->generic_constraints_pending = FALSE;
  tdsp->friend_depth_known = FALSE;
  tdsp->is_alias_redecl = FALSE;
  tdsp->is_var_templ_initial_decl = FALSE;
  tdsp->is_enum = FALSE;
  tdsp->caching_tokens = FALSE;
  tdsp->has_template_param_constraint = FALSE;
  tdsp->is_pack_element = FALSE;
  tdsp->is_pack_expansion = FALSE;
  tdsp->export_position = null_source_position;
  tdsp->other_decl_pos = null_source_position;
  tdsp->starting_token_sequence_number = NO_TOKEN_SEQUENCE_NUMBER;
  tdsp->last_token_sequence_number_of_params = NO_TOKEN_SEQUENCE_NUMBER;
  tdsp->access = (an_access_specifier)as_public;
  tdsp->nesting_depth = 0;
  tdsp->specialization_levels = 0;
  tdsp->final_token_ptr = NULL;
  tdsp->decl_info = NULL;
  tdsp->orig_decl_level = NO_SCOPE_DEPTH;
  tdsp->effective_decl_level = NO_SCOPE_DEPTH;
  tdsp->err_decl_level = NO_SCOPE_DEPTH;
  tdsp->number_of_template_decl_scopes = 0;
  tdsp->number_of_template_param_clauses = 0;
  tdsp->enclosing_scope = NULL;
  tdsp->class_declared_in = NULL;
  tdsp->param_list_cache = a_shared_token_cache();
  tdsp->first_decl_cache_tsn = NO_TOKEN_SEQUENCE_NUMBER;
  tdsp->decl_token_cache = a_shared_token_cache();
  tdsp->decl_token_cache_used = FALSE;
  tdsp->pragmas_bound_to_template = NULL;
  tdsp->il_template_entry = NULL;
  clear_decl_pos_block(&tdsp->decl_pos_block);
  tdsp->new_alias_symbol = NULL;
  tdsp->prototype_scope_symbols = NULL;
  tdsp->param_id_list = NULL;
  tdsp->bad_partial_spec_parent_class_sym = NULL;
  tdsp->out_of_class_prototype_sym = NULL;
#if EXTRA_SOURCE_POSITIONS_IN_IL
  tdsp->definition_range = null_source_range;
#endif /* EXTRA_SOURCE_POSITIONS_IN_IL */
  tdsp->template_decl = NULL;
  tdsp->requires_tsn = NO_TOKEN_SEQUENCE_NUMBER;
  tdsp->enclosing_param = NULL;
#if MICROSOFT_EXTENSIONS_ALLOWED
  tdsp->num_parameters = 0;
  tdsp->enclosing_generic_params = 0;
  tdsp->cli_class_type_kind = (a_cli_class_type_kind)cctk_standard;
  tdsp->cli_visibility = (an_assembly_visibility)av_none;
  tdsp->cli_visibility_pos = null_source_position;
#endif /* MICROSOFT_EXTENSIONS_ALLOWED */
}  /* init_templ_decl_state */


