  csp->orig_ctor_templ_params = NULL;
  csp->new_templ_params = NULL;
  csp->old_this_class = NULL;
  csp->new_this_class = NULL;
  csp->alias_parameter_pack_mapping = NULL;
  csp->record_used_arguments = NULL;
  csp->routine_type_levels = -1;
  csp->parent_levels = 0;
